<template><section aria-label="病例去标识技术任务目录"><p>仅技术目录；当前用途撤回后不会读取临床Source、Task、Result或原始问题。</p><template v-if="allowed"><el-button :disabled="busy" @click="load(1)">刷新病例去标识任务目录</el-button><el-table :data="rows" aria-label="病例去标识历史任务"><el-table-column prop="run_id" label="任务标识"/><el-table-column prop="status" label="记录状态"/><el-table-column label="当前读取范围"><template #default="{row}">{{ row.incomplete_native_artifact?'缺少永久来源，仅技术隔离':row.clinical_parts_available?'可按当前用途独立核对分件':'仅技术状态和实际用量' }}</template></el-table-column><el-table-column label="明确操作"><template #default="{row}"><el-button @click="open(row)">核对本条任务当前状态</el-button></template></el-table-column></el-table><template v-if="auditOnly"><el-button :disabled="busy||page<=1" @click="load(page-1)">上一页脱敏任务</el-button><span>第{{ page }}页，共{{ total }}件</span><el-button :disabled="busy||page*30>=total" @click="load(page+1)">下一页脱敏任务</el-button></template><p v-else>显示最近30条任务记录。</p></template><p v-else role="status">当前会话不能读取病例去标识任务目录。</p><p v-if="error" role="alert">{{ error }}</p></section></template>
<script setup>
import{computed,onActivated,onBeforeUnmount,onDeactivated,onMounted,ref,watch}from'vue';import{useStore}from'vuex';import{getDeidentificationSharedTasks,verifyDeidentificationSharedDirectoryRow}from'@/api/ai/deidentificationSharedTasks';import{deidentificationPolicy}from'@/api/ai/deidentificationSources';import{deidentificationCanonical as canonical,deidentificationId as uuid,same}from'@/api/ai/deidentificationCore';
const props=defineProps({active:{type:Boolean,default:true},auditOnly:{type:Boolean,default:false},caseId:{type:String,default:null}}),emit=defineEmits(['open','invalidate']),store=useStore(),rows=ref([]),busy=ref(false),error=ref(''),page=ref(1),total=ref(0),kept=ref(true);let epoch=0,alive=true,mounted=false,originals=new WeakMap();
const roles=computed(()=>store.state.user?.permissions),allowed=computed(()=>alive&&props.active&&kept.value&&!!store.state.user?.accessToken&&Array.isArray(roles.value)&&roles.value.every(x=>typeof x==='string')&&roles.value.some(x=>deidentificationPolicy.source_roles.includes(x))&&(!props.auditOnly||roles.value.includes('super_admin'))&&(props.caseId===null||uuid(props.caseId))),identity=()=>canonical([props.active,props.auditOnly,props.caseId,store.state.user?.accessToken,store.state.user?.username,roles.value]),current=t=>mounted&&allowed.value&&t.epoch===epoch&&t.identity===identity();
function clear(){epoch++;rows.value=[];busy.value=false;error.value='';total.value=0;originals=new WeakMap();}
async function load(selected=1){clear();if(!allowed.value)return;const t={epoch:++epoch,identity:identity()};busy.value=true;try{const response=await getDeidentificationSharedTasks({auditOnly:props.auditOnly,caseId:props.caseId,page:selected,pageSize:30});if(!current(t))return;for(const row of response.data)if(!await verifyDeidentificationSharedDirectoryRow(row,{auditOnly:props.auditOnly,current:()=>current(t)}))throw new Error();if(!current(t))return;rows.value=response.data;for(const row of rows.value)originals.set(row,JSON.parse(canonical(row)));page.value=selected;total.value=props.auditOnly?response.total:response.data.length;}catch{if(current(t)){clear();error.value='当前技术目录或原行身份无法核对，未保留旧目录。';}}finally{if(current(t))busy.value=false;}}
function open(row){const original=originals.get(row);if(!allowed.value||!original||!same(original,row)){clear();error.value='原目录行已变化，请刷新后明确选择。';return;}emit('open',original.run_id);}
watch([()=>props.active,()=>props.auditOnly,()=>props.caseId,()=>store.state.user?.accessToken,()=>store.state.user?.username,roles,kept],clear,{deep:true,flush:'sync'});onMounted(()=>{mounted=true;});onActivated(()=>{kept.value=true;});onDeactivated(()=>{kept.value=false;});onBeforeUnmount(()=>{alive=false;mounted=false;clear();});defineExpose({load,clear});
</script>
